def search_models(query, collection_id=None, visibility=None, model_type=None, status=None, tags=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, api_key_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "rplog_" + hashlib.sha256(f"{now}|search_models|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "search_models",
            "api_key_id": api_key_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if message:
            entry["message"] = message
        logs.append(entry)
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1 or obj.get("tool") != "search_models":
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(offset):
        payload = {"v": 1, "tool": "search_models", "offset": offset}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _safe_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Ambient auth resolution (pick any active key); needed for rate limiting dynamics.
    api_keys = _load("api_keys.json")
    api_key = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break
    if api_key is None:
        _log("UNAUTHORIZED", None, "No active API key available for ambient authentication")
        return _err("UNAUTHORIZED", "No active API key is available to authorize this request.")

    # Rate limit enforcement per api_key.rate_limit_rpm
    rpm = api_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        _log("UNAUTHORIZED", api_key.get("id"), "API key has invalid rate limit configuration")
        return _err("UNAUTHORIZED", "API key is misconfigured.")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60))
    used = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key.get("id"):
            continue
        ts = _safe_dt(e.get("timestamp"))
        if ts is None:
            continue
        if ts >= window_start.replace(tzinfo=ts.tzinfo):
            used += 1
    if used >= rpm:
        _log("RATE_LIMIT", api_key.get("id"), "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit=rpm, window_seconds=60)

    # Input validation
    if not isinstance(query, str) or not query.strip():
        _log("VALIDATION_ERROR", api_key.get("id"), "query missing/empty")
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string.", field="query")

    if collection_id is not None:
        if not isinstance(collection_id, str) or re.match(r"^rpcoll_[0-9A-Z]{16,}$", collection_id) is None:
            _log("VALIDATION_ERROR", api_key.get("id"), "collection_id pattern invalid")
            return _err("VALIDATION_ERROR", "collection_id must match ^rpcoll_[0-9A-Z]{16,}$.", field="collection_id")

    if visibility is not None:
        if visibility not in ("public", "private", "unlisted"):
            _log("VALIDATION_ERROR", api_key.get("id"), "visibility invalid")
            return _err("VALIDATION_ERROR", "visibility must be one of: public, private, unlisted.", field="visibility")
    if model_type is not None:
        if model_type not in ("official", "community"):
            _log("VALIDATION_ERROR", api_key.get("id"), "model_type invalid")
            return _err("VALIDATION_ERROR", "model_type must be one of: official, community.", field="model_type")
    if status is not None:
        if status not in ("active", "deprecated", "disabled"):
            _log("VALIDATION_ERROR", api_key.get("id"), "status invalid")
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled.", field="status")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _log("VALIDATION_ERROR", api_key.get("id"), "tags invalid")
            return _err("VALIDATION_ERROR", "tags must be an array of strings.", field="tags")

    if sort is not None:
        if sort not in ("rank", "run_count_30d", "created_at", "updated_at"):
            _log("VALIDATION_ERROR", api_key.get("id"), "sort invalid")
            return _err("VALIDATION_ERROR", "sort must be one of: rank, run_count_30d, created_at, updated_at.", field="sort")
    else:
        sort = "rank"

    if order is not None:
        if order not in ("asc", "desc"):
            _log("VALIDATION_ERROR", api_key.get("id"), "order invalid")
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")
    else:
        order = "asc"

    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("VALIDATION_ERROR", api_key.get("id"), "limit invalid")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    else:
        limit = 20

    offset = _parse_cursor(cursor)
    if offset is None:
        _log("VALIDATION_ERROR", api_key.get("id"), "cursor malformed")
        return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    # Data load
    models = _load("models.json")
    if not isinstance(models, list):
        models = []

    # Business rule: only public models for non-internal callers (no explicit access modeled)
    effective_visibility_restriction = "public"

    q = query.strip().lower()
    q_tokens = [tok for tok in re.split(r"\s+", q) if tok]

    def _text_of(m):
        parts = []
        for k in ("name", "owner", "full_name", "description"):
            v = m.get(k)
            if isinstance(v, str) and v:
                parts.append(v)
        tg = m.get("tags")
        if isinstance(tg, list):
            parts.extend([t for t in tg if isinstance(t, str)])
        return " ".join(parts).lower()

    def _matches_query(m):
        text = _text_of(m)
        # Require all tokens to be present somewhere (simple AND)
        for tok in q_tokens:
            if tok not in text:
                return False
        return True

    # Apply filters
    filtered = []
    for m in models:
        if not isinstance(m, dict):
            continue

        # visibility restriction
        if m.get("visibility") != effective_visibility_restriction:
            continue

        if collection_id is not None and m.get("collection_id") != collection_id:
            continue
        if visibility is not None and m.get("visibility") != visibility:
            continue
        if model_type is not None and m.get("model_type") != model_type:
            continue
        if status is not None and m.get("status") != status:
            continue
        if tags is not None:
            mtags = m.get("tags")
            if not isinstance(mtags, list):
                continue
            mtags_set = set([t for t in mtags if isinstance(t, str)])
            ok = True
            for t in tags:
                if t not in mtags_set:
                    ok = False
                    break
            if not ok:
                continue
        if not _matches_query(m):
            continue

        filtered.append(m)

    # Sorting
    reverse = (order == "desc")

    def _sort_key(m):
        if sort == "rank":
            v = m.get("rank")
            return (v if isinstance(v, int) else 10**18, m.get("id") or "")
        if sort == "run_count_30d":
            v = m.get("run_count_30d")
            return (v if isinstance(v, int) else -1, m.get("id") or "")
        if sort == "created_at":
            dt = _safe_dt(m.get("created_at"))
            return (dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), m.get("id") or "")
        if sort == "updated_at":
            dt = _safe_dt(m.get("updated_at"))
            return (dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), m.get("id") or "")
        return (m.get("id") or "")

    # For rank, "asc" implies lower rank first; for others, "desc" often expected, but we honor order verbatim.
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    # Update last_used_at for successful request dynamics
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    _log("OK", api_key.get("id"))

    return {
        "models": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor
        }
    }

