            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1 or obj.get("tool") != "list_collections":
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(offset):
        payload = {"v": 1, "tool": "list_collections", "offset": offset}
        b = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("utf-8").rstrip("=")

    def _safe_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Ambient auth resolution
    api_keys = _load("api_keys.json")
    api_key = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break
    if api_key is None:
        _log("UNAUTHORIZED", None, "No active API key available for ambient authentication")
        return _err("UNAUTHORIZED", "No active API key is available to authorize this request.")

    # Enforce quota for collection listing requests (policy: 10,000 per billing month per key)
    # Stored implicitly via request_logs; count current billing month.
    billing_month = api_key.get("billing_month")
    if not isinstance(billing_month, str) or not re.match(r"^\d{4}-\d{2}$", billing_month):
        billing_month = datetime.datetime.utcnow().strftime("%Y-%m")
    quota_limit = 10000
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    month_prefix = billing_month + "-"
    quota_used = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key.get("id"):
            continue
        if e.get("endpoint") != "list_collections":
            continue
        ts = e.get("timestamp")
        if isinstance(ts, str) and ts.startswith(month_prefix):
            quota_used += 1
    if quota_used >= quota_limit:
        _log("QUOTA_EXCEEDED", api_key.get("id"), "Collection listing quota exceeded")
        return _err("QUOTA_EXCEEDED", "Collection listing quota exceeded for the current billing month.", limit=quota_limit, used=quota_used, billing_month=billing_month)

    # Rate limit enforcement (also applies)
    rpm = api_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        _log("UNAUTHORIZED", api_key.get("id"), "API key has invalid rate limit configuration")
        return _err("UNAUTHORIZED", "API key is misconfigured.")
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60))
    used = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key.get("id"):
            continue
        ts = _safe_dt(e.get("timestamp"))
        if ts is None:
            continue
        if ts >= window_start.replace(tzinfo=ts.tzinfo):
            used += 1
    if used >= rpm:
        _log("RATE_LIMIT", api_key.get("id"), "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit=rpm, window_seconds=60)

    # Validation
    if status is not None:
        if status not in ("active", "hidden", "archived"):
            _log("VALIDATION_ERROR", api_key.get("id"), "status invalid")
            return _err("VALIDATION_ERROR", "status must be one of: active, hidden, archived.", field="status")

    if sort is not None:
        if sort not in ("rank", "created_at", "updated_at"):
            _log("VALIDATION_ERROR", api_key.get("id"), "sort invalid")
            return _err("VALIDATION_ERROR", "sort must be one of: rank, created_at, updated_at.", field="sort")
    else:
        sort = "rank"

    if order is not None:
        if order not in ("asc", "desc"):
            _log("VALIDATION_ERROR", api_key.get("id"), "order invalid")
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")
    else:
        order = "asc"

    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("VALIDATION_ERROR", api_key.get("id"), "limit invalid")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    else:
        limit = 20

    offset = _parse_cursor(cursor)
    if offset is None:
        _log("VALIDATION_ERROR", api_key.get("id"), "cursor malformed")
        return _err("VALIDATION_ERROR", "cursor is malformed.", field="cursor")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    # Business rule: exclude archived by default unless internal flag (not exposed).
    # So if status is None: include active + hidden only.
    filtered = []
    for c in collections:
        if not isinstance(c, dict):
            continue
        c_status = c.get("status")
        if status is None:
            if c_status not in ("active", "hidden"):
                continue
        else:
            if c_status != status:
                continue
            # Even if requested archived, non-internal callers can't see it.
            if status == "archived":
                continue
        filtered.append(c)

    reverse = (order == "desc")

    def _sort_key(c):
        if sort == "rank":
            v = c.get("rank")
            return (v if isinstance(v, int) else 10**18, c.get("id") or "")
        if sort == "created_at":
            dt = _safe_dt(c.get("created_at"))
            return (dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), c.get("id") or "")
        if sort == "updated_at":
            dt = _safe_dt(c.get("updated_at"))
            return (dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), c.get("id") or "")
        return (c.get("id") or "")

    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    _log("OK", api_key.get("id"))

    return {
        "collections": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor
        }
    }

def get_collection(collection_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _safe_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status_code, api_key_id=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "rplog_" + hashlib.sha256(f"{now}|get_collection|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "get_collection",
            "api_key_id": api_key_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if message:
            entry["message"] = message
        logs.append(entry)
        _save("request_logs.json", logs)

    # Ambient auth resolution + rate limit enforcement
    api_keys = _load("api_keys.json")
    api_key = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break
    if api_key is None:
        _log("UNAUTHORIZED", None, "No active API key available for ambient authentication")
        return _err("UNAUTHORIZED", "No active API key is available to authorize this request.")

    rpm = api_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        _log("UNAUTHORIZED", api_key.get("id"), "API key has invalid rate limit configuration")
        return _err("UNAUTHORIZED", "API key is misconfigured.")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60))
    used = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key.get("id"):
            continue
        ts = _safe_dt(e.get("timestamp"))
        if ts is None:
            continue
        if ts >= window_start.replace(tzinfo=ts.tzinfo):
            used += 1
    if used >= rpm:
        _log("RATE_LIMIT", api_key.get("id"), "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit=rpm, window_seconds=60)

    # Validation
    if not isinstance(collection_id, str) or re.match(r"^rpcoll_[0-9A-Z]{16,}$", collection_id) is None:
        _log("VALIDATION_ERROR", api_key.get("id"), "collection_id pattern invalid")
        return _err("VALIDATION_ERROR", "collection_id must match ^rpcoll_[0-9A-Z]{16,}$.", field="collection_id")

    collections = _load("collections.json")
    if not isinstance(collections, list):
        collections = []

    col = None
    for c in collections:
        if isinstance(c, dict) and (c.get("id") == collection_id or c.get("slug") == collection_id):
            col = c
            break

    if col is None:
        _log("NOT_FOUND", api_key.get("id"), "collection not found")
        return _err("NOT_FOUND", "No collection exists with that id.", collection_id=collection_id)

    # Authorization/visibility: archived collections are not visible to non-internal callers
    if col.get("status") == "archived":
        _log("UNAUTHORIZED", api_key.get("id"), "collection not visible")
        return _err("UNAUTHORIZED", "You do not have access to this collection.", collection_id=collection_id)

    models = _load("models.json")
    if not isinstance(models, list):
        models = []

    # Associated models by collection_id; only public models (no private access modeled)
    assoc = []
    for m in models:
        if not isinstance(m, dict):
            continue
        if m.get("collection_id") != col.get("id"):
            continue
        if m.get("visibility") != "public":
            continue
        assoc.append(m)

    # default ordering: by rank asc then id
    assoc.sort(key=lambda m: ((m.get("rank") if isinstance(m.get("rank"), int) else 10**18), (m.get("id") or "")))

    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    _log("OK", api_key.get("id"))

    return {
        "collection": col,
        "models": assoc,
        "meta": {
            "models_total": len(assoc)
        }
    }

def create_prediction(input, model_version_id=None, model_name=None, version=None, webhook_url=None, webhook_events_filter=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _append_request_log(endpoint, api_key_id, status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rpreq_" + uuid.uuid4().hex[:20].upper(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _month_bucket(dt_utc):
        return f"{dt_utc.year:04d}-{dt_utc.month:02d}"

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex[:20].upper()

    def _extract_urls(obj, out, cap=500):
        if len(out) >= cap:
            return
        if isinstance(obj, str):
            if obj.startswith("http://") or obj.startswith("https://"):
                out.append(obj)
            return
        if isinstance(obj, list):
            for it in obj:
                if len(out) >= cap:
                    break
                _extract_urls(it, out, cap=cap)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                if len(out) >= cap:
                    break
                _extract_urls(v, out, cap=cap)

    def _choose_ambient_api_key(api_keys_rows):
        # No explicit credential parameter; choose any ACTIVE key that can serve requests.
        # If none active exist, it's unauthorized.
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _enforce_rate_limit(api_key_row, request_logs_rows):
        # rate_limit_rpm per key, within last 60 seconds, counted across all endpoints
        try:
            rpm = api_key_row.get("rate_limit_rpm")
        except Exception:
            rpm = None
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            return _err("VALIDATION_ERROR", "API key has invalid rate_limit_rpm configuration.", api_key_id=api_key_row.get("id"))
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        if c >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit_rpm=rpm)
        return None

    # Validate required input
    if not isinstance(input, dict):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "input must be an object")
        return _err("VALIDATION_ERROR", "input must be an object.")

    # Validate webhook filters
    allowed_events = {"starting", "processing", "succeeded", "failed", "canceled"}
    if webhook_events_filter is None:
        webhook_events_filter = []
    if not isinstance(webhook_events_filter, list) or any((not isinstance(x, str) or x not in allowed_events) for x in webhook_events_filter):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "webhook_events_filter must be an array of valid event strings")
        return _err("VALIDATION_ERROR", "webhook_events_filter must be an array containing only: starting, processing, succeeded, failed, canceled.")

    if webhook_url is not None and (not isinstance(webhook_url, str) or webhook_url.strip() == ""):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "webhook_url must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "webhook_url must be a non-empty string when provided.")

    # Validate patterns minimally per tool schema
    if model_version_id is not None:
        if not isinstance(model_version_id, str) or not re.match(r"^rpver_[0-9A-Z]{16,}$", model_version_id):
            _append_request_log("create_prediction", None, "VALIDATION_ERROR", "model_version_id does not match required pattern")
            return _err("VALIDATION_ERROR", "model_version_id does not match required pattern.")

    # IMPORTANT: Relax the overly-strict mutual exclusion: parameter schema allows model_version_id and model_name together.
    # Business rule is about what the prediction references, not about which optional parameters were passed.
    if model_version_id is None and (model_name is None or (isinstance(model_name, str) and model_name.strip() == "")):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "must supply model_version_id or model_name")
        return _err("VALIDATION_ERROR", "Must provide either model_version_id (community/versioned) or model_name (official).")

    if model_name is not None and not isinstance(model_name, str):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "model_name must be string when provided")
        return _err("VALIDATION_ERROR", "model_name must be a string when provided.")

    if version is not None and not isinstance(version, str):
        _append_request_log("create_prediction", None, "VALIDATION_ERROR", "version must be string when provided")
        return _err("VALIDATION_ERROR", "version must be a string when provided.")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    predictions = _load("predictions.json")
    if not isinstance(predictions, list):
        predictions = []
    models = _load("models.json")
    if not isinstance(models, list):
        models = []
    model_versions = _load("model_versions.json")
    if not isinstance(model_versions, list):
        model_versions = []

    # Ambient authentication: find a usable active api_key.
    api_key = _choose_ambient_api_key(api_keys)
    if not api_key:
        _append_request_log("create_prediction", None, "UNAUTHORIZED", "no active api key available")
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # Enforce per-minute rate limit using request logs BEFORE recording this call.
    rl_err = _enforce_rate_limit(api_key, request_logs)
    if rl_err:
        _append_request_log("create_prediction", api_key.get("id"), rl_err["error"]["code"], rl_err["error"]["message"])
        return rl_err

    # Enforce concurrent prediction limit
    mcp = api_key.get("max_concurrent_predictions")
    if not isinstance(mcp, int) or mcp < 1 or mcp > 1000:
        _append_request_log("create_prediction", api_key.get("id"), "VALIDATION_ERROR", "invalid max_concurrent_predictions config")
        return _err("VALIDATION_ERROR", "API key has invalid max_concurrent_predictions configuration.", api_key_id=api_key.get("id"))
    concurrent = 0
    for p in predictions:
        if not isinstance(p, dict):
            continue
        if p.get("api_key_id") == api_key.get("id") and p.get("status") in ("starting", "processing"):
            concurrent += 1
    if concurrent >= mcp:
        _append_request_log("create_prediction", api_key.get("id"), "CONFLICT", "too many concurrent predictions")
        return _err("CONFLICT", "Too many concurrent predictions for this API key.", max_concurrent_predictions=mcp)

    if api_key.get("status") != "active":
        _append_request_log("create_prediction", api_key.get("id"), "UNAUTHORIZED", "api key not active")
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=api_key.get("id"))

    # Billing month rollover (server-side behavior)
    curr_bucket = _month_bucket(now_dt)
    if isinstance(api_key.get("billing_month"), str) and api_key.get("billing_month") != curr_bucket:
        api_key["billing_month"] = curr_bucket
        api_key["monthly_spend_used_usd"] = 0.0
        api_key["updated_at"] = now

    # Resolve model reference
    resolved_model = None
    resolved_version = None
    use_versioned = False

    if model_version_id is not None:
        # Community/versioned flow: model_version_id must exist and not be disabled
        resolved_version = next((v for v in model_versions if isinstance(v, dict) and v.get("id") == model_version_id), None)
        if not resolved_version:
            _append_request_log("create_prediction", api_key.get("id"), "NOT_FOUND", "model version not found")
            return _err("NOT_FOUND", "Model version not found.", model_version_id=model_version_id)
        if resolved_version.get("status") == "disabled":
            _append_request_log("create_prediction", api_key.get("id"), "CONFLICT", "model version disabled")
            return _err("CONFLICT", "Model version is disabled and cannot be run.", model_version_id=model_version_id)
        resolved_model = next((m for m in models if isinstance(m, dict) and m.get("id") == resolved_version.get("model_id")), None)
        if not resolved_model:
            _append_request_log("create_prediction", api_key.get("id"), "NOT_FOUND", "parent model not found for version")
            return _err("NOT_FOUND", "Parent model for model_version_id not found.", model_version_id=model_version_id)
        use_versioned = True

    if not use_versioned:
        # Official model flow: map model_name to models.full_name if possible, else try (owner/name) passthrough
        req_name = model_name.strip() if isinstance(model_name, str) else ""
        # Allow "whisper" style: match by name field if unique among official models; else require full_name
        candidates = []
        for m in models:
            if not isinstance(m, dict):
                continue
            if m.get("status") == "disabled":
                continue
            if m.get("visibility") != "public":
                continue
            if req_name == m.get("full_name") or req_name == m.get("name"):
                candidates.append(m)
        if len(candidates) == 1:
            resolved_model = candidates[0]
        elif len(candidates) > 1:
            _append_request_log("create_prediction", api_key.get("id"), "CONFLICT", "ambiguous model_name")
            return _err("CONFLICT", "model_name is ambiguous; provide full owner/name.", model_name=req_name)
        else:
            _append_request_log("create_prediction", api_key.get("id"), "NOT_FOUND", "model not found")
            return _err("NOT_FOUND", "Model not found or not publicly accessible.", model_name=req_name)

        # Resolve requested vendor version if provided, otherwise default_version_id or latest_version_id
        if isinstance(version, str) and version.strip() != "":
            v = next((mv for mv in model_versions if isinstance(mv, dict) and mv.get("model_id") == resolved_model.get("id") and mv.get("vendor_version") == version), None)
            if not v:
                _append_request_log("create_prediction", api_key.get("id"), "NOT_FOUND", "vendor version not found for model")
                return _err("NOT_FOUND", "Requested version not found for model.", model_name=resolved_model.get("full_name"), version=version)
            if v.get("status") == "disabled":
                _append_request_log("create_prediction", api_key.get("id"), "CONFLICT", "requested version disabled")
                return _err("CONFLICT", "Requested version is disabled and cannot be run.", version=version)
            resolved_version = v
        else:
            dv_id = resolved_model.get("default_version_id") or resolved_model.get("latest_version_id")
            if isinstance(dv_id, str):
                v = next((mv for mv in model_versions if isinstance(mv, dict) and mv.get("id") == dv_id), None)
                if v and v.get("status") != "disabled":
                    resolved_version = v
            # If no usable version pointer, allow prediction without model_version_id? Business rule requires exactly one reference.
            if not resolved_version:
                _append_request_log("create_prediction", api_key.get("id"), "CONFLICT", "no runnable version available for model")
                return _err("CONFLICT", "No runnable version available for this model.", model_name=resolved_model.get("full_name"))

    # Enforce "exactly one of model_id or model_version_id" at the stored row level.
    # If user provided model_version_id, we store model_version_id and leave model_id null.
    # Otherwise store model_id and leave model_version_id null.
    stored_model_id = None
    stored_model_version_id = None
    requested_model_name = None
    requested_version = None

    if use_versioned:
        stored_model_version_id = resolved_version.get("id")
        requested_version = resolved_version.get("vendor_version")
        # If caller passed model_name too, we store it as requested_model_name for traceability (not a validation error)
        if isinstance(model_name, str) and model_name.strip():
            requested_model_name = model_name.strip()
    else:
        stored_model_id = resolved_model.get("id")
        requested_model_name = resolved_model.get("full_name")
        requested_version = resolved_version.get("vendor_version")

    if (stored_model_id is not None) and (stored_model_version_id is not None):
        _append_request_log("create_prediction", api_key.get("id"), "VALIDATION_ERROR", "would store both model_id and model_version_id")
        return _err("VALIDATION_ERROR", "Business rule violated: prediction must reference exactly one of model_id (official) or model_version_id (community/versioned).")

    # Spend limit enforcement (consistent policy): only block if we can estimate the cost up front
    spend_limit = api_key.get("monthly_spend_limit_usd")
    spend_used = api_key.get("monthly_spend_used_usd")
    if not isinstance(spend_used, (int, float)) or spend_used < 0:
        spend_used = 0.0
    est_cost = None
    if isinstance(resolved_version, dict):
        pps = resolved_version.get("price_per_second_usd")
        mins = resolved_version.get("min_runtime_seconds")
        if isinstance(pps, (int, float)) and pps >= 0 and isinstance(mins, int) and mins >= 0:
            est_cost = float(pps) * float(mins)
    if isinstance(spend_limit, (int, float)) and spend_limit >= 0 and est_cost is not None:
        if float(spend_used) + float(est_cost) > float(spend_limit) + 1e-9:
            _append_request_log("create_prediction", api_key.get("id"), "QUOTA_EXCEEDED", "monthly spend limit would be exceeded")
            return _err("QUOTA_EXCEEDED", "Monthly spend limit would be exceeded by estimated cost.", monthly_spend_limit_usd=float(spend_limit), monthly_spend_used_usd=float(spend_used), estimated_cost_usd=float(est_cost))

    # Create prediction row
    pred_id = _new_id("rppred")
    vendor_pred_id = "rprun_" + uuid.uuid4().hex[:20].upper()
    new_pred = {
        "id": pred_id,
        "vendor_prediction_id": vendor_pred_id,
        "api_key_id": api_key.get("id"),
        "model_id": stored_model_id,
        "model_version_id": stored_model_version_id,
        "requested_model_name": requested_model_name,
        "requested_version": requested_version,
        "input": input,
        "status": "starting",
        "created_at": now,
        "started_at": None,
        "completed_at": None,
        "updated_at": now,
        "output": None,
        "output_urls": [],
        "error_message": None,
        "logs_url": None,
        "cancel_requested_at": None,
        "canceled_at": None,
        "runtime_seconds": None,
        "cost_usd": None,
        "webhook_url": webhook_url,
