    }

def cancel_prediction(prediction_id, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _append_request_log(endpoint, api_key_id, status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rpreq_" + uuid.uuid4().hex[:20].upper(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(api_key_row, request_logs_rows):
        rpm = api_key_row.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
            return _err("VALIDATION_ERROR", "API key has invalid rate_limit_rpm configuration.", api_key_id=api_key_row.get("id"))
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts and ts >= cutoff:
                c += 1
        if c >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", limit_rpm=rpm)
        return None

    # Validate inputs (vendor schema requires rppred_*). Do not accept other ids.
    if not isinstance(prediction_id, str) or not prediction_id:
        return _err("VALIDATION_ERROR", "prediction_id must be a non-empty string.", prediction_id=prediction_id)
    if not re.match(r"^rppred_[0-9A-Z]{16,}$", prediction_id):
        return _err("VALIDATION_ERROR", "prediction_id does not match required pattern '^rppred_[0-9A-Z]{16,}$'.", prediction_id=prediction_id)

    # Authenticate ambiently: choose any ACTIVE api_key that can access this prediction.
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    preds = _load("predictions.json")
    if not isinstance(preds, list):
        preds = []

    pred = None
    for p in preds:
        if isinstance(p, dict) and p.get("id") == prediction_id:
            pred = p
            break
    if pred is None:
        # Log with unknown key context
        _append_request_log("cancel_prediction", None, 404, "Prediction not found")
        return _err("NOT_FOUND", "Prediction not found.", prediction_id=prediction_id)

    # Find serving key context: must be active and match prediction's api_key_id
    pred_key_id = pred.get("api_key_id")
    chosen_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == pred_key_id and k.get("status") == "active":
            chosen_key = k
            break
    if chosen_key is None:
        # If the owning key isn't active/available, caller can't be authorized under our store model.
        _append_request_log("cancel_prediction", pred_key_id, 401, "No active API key context for this prediction")
        return _err("UNAUTHORIZED", "You do not have access to this prediction (no active API key context found).", prediction_id=prediction_id)

    # Enforce rate limit for this key (observable dynamics: every call logs)
    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    rl_err = _enforce_rate_limit(chosen_key, request_logs)
    if rl_err:
        _append_request_log("cancel_prediction", chosen_key.get("id"), 429, rl_err["error"]["message"])
        return rl_err

    # Business rule: cancel allowed only for starting/processing
    status = pred.get("status")
    if status not in ("starting", "processing"):
        _append_request_log("cancel_prediction", chosen_key.get("id"), 409, "Prediction already in terminal state")
        return _err("CONFLICT", "Cannot cancel prediction because it is already in a terminal state.", prediction_id=prediction_id, status=status)

    # Idempotency: if cancel already requested, return as-is but still update updated_at/last_used and log.
    changed = False
    if pred.get("cancel_requested_at") is None:
        pred["cancel_requested_at"] = now
        changed = True

    # Upstream confirmation not modeled; treat as immediately confirmed to satisfy local backend semantics.
    # Transition to canceled (legal from starting/processing).
    pred["status"] = "canceled"
    pred["canceled_at"] = pred.get("canceled_at") or now
    pred["completed_at"] = pred.get("completed_at") or now
    pred["updated_at"] = now
    changed = True

    # Persist mutation (NO SUCCESS WITHOUT EFFECT)
    if not changed:
        _append_request_log("cancel_prediction", chosen_key.get("id"), 404, "No changes applied")
        return _err("NOT_FOUND", "Prediction not found or could not be modified.", prediction_id=prediction_id)

    # Save back predictions
    for i, p in enumerate(preds):
        if isinstance(p, dict) and p.get("id") == prediction_id:
            preds[i] = pred
            break
    _save("predictions.json", preds)

    # Update api key last_used_at/updated_at
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == chosen_key.get("id"):
            api_keys[i] = dict(k)
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = now
            chosen_key = api_keys[i]
            break
    _save("api_keys.json", api_keys)

    _append_request_log("cancel_prediction", chosen_key.get("id"), 200, None)

    # Return updated prediction record (subset per rule description)
    return {
        "prediction": {
            "id": pred.get("id"),
            "vendor_prediction_id": pred.get("vendor_prediction_id"),
            "status": pred.get("status"),
            "input": pred.get("input"),
            "output": pred.get("output"),
            "logs_url": pred.get("logs_url"),
            "created_at": pred.get("created_at"),
            "started_at": pred.get("started_at"),
            "completed_at": pred.get("completed_at"),
            "updated_at": pred.get("updated_at"),
            "cancel_requested_at": pred.get("cancel_requested_at"),
            "canceled_at": pred.get("canceled_at"),
            "error_message": pred.get("error_message"),
            "output_urls": pred.get("output_urls"),
            "runtime_seconds": pred.get("runtime_seconds"),
            "cost_usd": pred.get("cost_usd"),
            "webhook_url": pred.get("webhook_url"),
            "webhook_events_filter": pred.get("webhook_events_filter"),
            "requested_model_name": pred.get("requested_model_name"),
            "requested_version": pred.get("requested_version"),
            "model_id": pred.get("model_id"),
            "model_version_id": pred.get("model_version_id"),
        }
    }

