def list_predictions(status=None, model_id=None, model_version_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(endpoint, api_key_id, status_code, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rpreq_" + uuid.uuid4().hex[:20].upper(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate
    allowed_status = {"starting", "processing", "succeeded", "failed", "canceled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "invalid status")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=list(sorted(allowed_status)))

    if model_id is not None and (not isinstance(model_id, str) or not re.match(r"^rpmdl_[0-9A-Z]{16,}$", model_id)):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "model_id pattern mismatch")
        return _err("VALIDATION_ERROR", "model_id must match ^rpmdl_[0-9A-Z]{16,}$")

    if model_version_id is not None and (not isinstance(model_version_id, str) or not re.match(r"^rpver_[0-9A-Z]{16,}$", model_version_id)):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "model_version_id pattern mismatch")
        return _err("VALIDATION_ERROR", "model_version_id must match ^rpver_[0-9A-Z]{16,}$")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at"):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    if cursor is not None and not isinstance(cursor, str):
        _append_request_log("list_predictions", None, "VALIDATION_ERROR", "cursor must be string")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Resolve ambient key: any active key can list its own predictions; choose one that actually has predictions (or any active).
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    predictions = _load("predictions.json")
    if not isinstance(predictions, list):
        predictions = []

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _append_request_log("list_predictions", None, "UNAUTHORIZED", "no active api keys")
        return _err("UNAUTHORIZED", "No authorized API key available to perform this operation.")

    # prefer key with any predictions
    key = None
    pred_key_ids = {p.get("api_key_id") for p in predictions if isinstance(p, dict)}
    for k in active_keys:
        if k.get("id") in pred_key_ids:
            key = k
            break
    if key is None:
        key = sorted(active_keys, key=lambda k: k.get("created_at") or "")[0]

    api_key_id = key.get("id")

    # Cursor decoding: base64 JSON {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                _append_request_log("list_predictions", api_key_id, "VALIDATION_ERROR", "bad cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["offset"]
        except Exception:
            _append_request_log("list_predictions", api_key_id, "VALIDATION_ERROR", "bad cursor parse")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    def _parse_dt(s):
        if not s: return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Filter to this api_key_id
    rows = [p for p in predictions if isinstance(p, dict) and p.get("api_key_id") == api_key_id]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if model_id is not None:
        rows = [p for p in rows if p.get("model_id") == model_id]
    if model_version_id is not None:
        rows = [p for p in rows if p.get("model_version_id") == model_version_id]

    reverse = (order == "desc")
    rows.sort(key=lambda p: (_parse_dt(p.get(sort)) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), p.get("id") or ""), reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # update last_used_at
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    _append_request_log("list_predictions", api_key_id, "OK", None)

    return {
        "predictions": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

