    if not isinstance(include_versions, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_versions must be a boolean.", field="include_versions")

    if include_versions:
        if versions_limit is None:
            versions_limit = 20
        if not isinstance(versions_limit, int) or not (1 <= versions_limit <= 100):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "versions_limit must be an integer between 1 and 100.", field="versions_limit")
        if versions_cursor is not None:
            if not isinstance(versions_cursor, str) or not re.match(r"^rvc_[0-9A-HJKMNP-TV-Z]{10,}$", versions_cursor):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "versions_cursor is malformed.", field="versions_cursor")

    models = _load("models.json")
    model = None
    for m in models:
        if isinstance(m, dict) and m.get("id") == model_id:
            model = m
            break
    if model is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Model not found.", model_id=model_id)

    # Business rule: non-internal callers cannot see disabled versions; and only public models by default.
    # "Explicit access not modeled" => enforce public-only for safety.
    if model.get("visibility") != "public":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Model not found.", model_id=model_id)

    # Prepare response
    resp = {"model": model}

    if include_versions:
        versions = _load("model_versions.json")
        rows = []
        for v in versions:
            if not isinstance(v, dict):
                continue
            if v.get("model_id") != model_id:
                continue
            if v.get("status") == "disabled":
                continue
            rows.append(v)

        def _parse_dt(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=True)

        start = 0
        if versions_cursor is not None:
            # cursor encodes "rvc_<created_at_iso>_<id>" but we accept only existence by scanning exact match
            # We'll interpret cursor as opaque pointer to last seen version id if present.
            # Opaque format: rvc_<version_id>
            if versions_cursor.startswith("rvc_"):
                last_id = versions_cursor[4:]
                idx = None
                for i, r in enumerate(rows):
                    if r.get("id") == last_id:
                        idx = i
                        break
                if idx is None:
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "versions_cursor is malformed.", field="versions_cursor")
                start = idx + 1

        page = rows[start:start + versions_limit]
        has_more = (start + versions_limit) < len(rows)
        next_cursor = ("rvc_" + page[-1]["id"]) if (has_more and page) else None

        resp["versions"] = {
            "data": page,
            "limit": versions_limit,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor
        }

    # touch api_key last_used_at on successful auth-context usage
    if authed_key is not None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    _log("ok", None)
    return resp

def view_image(url, prediction_id=None, open_in_browser=None, **_extra):
    import json, os, datetime, re, time, hashlib, urllib.parse, mimetypes, urllib.request, webbrowser

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    api_keys = _load("api_keys.json")
    authed_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            authed_key = k
            break

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status, error_code=None):
        entry = {
            "id": "rplog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "view_image",
            "api_key_id": authed_key.get("id") if isinstance(authed_key, dict) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        request_logs.append(entry)
        _save("request_logs.json", request_logs)

    # Rate limit
    if authed_key is not None:
        rpm = authed_key.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized API key context available for this operation.")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != authed_key.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            _log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate url (uri)
    if not isinstance(url, str) or not url.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url must be a non-empty string.", field="url")
    try:
        pu = urllib.parse.urlparse(url)
    except Exception:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url is not a valid URI.", field="url")
    if pu.scheme not in ("http", "https") or not pu.netloc:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url is not a valid URI.", field="url")

    if prediction_id is not None:
        if not isinstance(prediction_id, str) or not re.match(r"^rppred_[0-9A-HJKMNP-TV-Z]{16,}$", prediction_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "prediction_id does not match required pattern.", field="prediction_id")

    if open_in_browser is None:
        open_in_browser = False
    if not isinstance(open_in_browser, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "open_in_browser must be a boolean.", field="open_in_browser")

    # If prediction_id supplied, must exist
    if prediction_id is not None:
        preds = _load("predictions.json")
        found = False
        for p in preds:
            if isinstance(p, dict) and (p.get("id") == prediction_id or p.get("vendor_prediction_id") == prediction_id):
                found = True
                break
        if not found:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Prediction not found.", prediction_id=prediction_id)

    # Upsert cache entry by url_sha256
    url_sha = hashlib.sha256(url.encode("utf-8")).hexdigest()
    entries = _load("image_cache_entries.json")
    if not isinstance(entries, list):
        entries = []

    entry = None
    for e in entries:
        if isinstance(e, dict) and e.get("url_sha256") == url_sha:
            entry = e
            break

    if entry is None:
        entry = {
            "id": "rpimg_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "url": url,
            "url_sha256": url_sha,
            "content_type": None,
            "byte_size": None,
            "local_path": None,
            "status": "error",  # until download succeeds
            "last_viewed_at": None,
            "downloaded_at": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        entries.append(entry)
    else:
        # keep url fresh
        entry["url"] = url
        entry["updated_at"] = now

    # attempt download/cache
    cache_dir = os.path.join(_DB, "image_cache")
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except Exception:
        # filesystem failure
        entry["status"] = "error"
        entry["error_message"] = "Failed to create cache directory."
        entry["updated_at"] = now
        entry["last_viewed_at"] = now
        _save("image_cache_entries.json", entries)
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to initialize image cache directory.")

    local_path = os.path.join(cache_dir, url_sha)
    tmp_path = local_path + ".tmp"

    def _guess_ext(content_type, url_):
        ext = None
        if content_type:
            ext = mimetypes.guess_extension(content_type.split(";")[0].strip())
        if not ext:
            path = urllib.parse.urlparse(url_).path
            _, e = os.path.splitext(path)
            if e and len(e) <= 10:
                ext = e
        return ext or ""

    try:
        req = urllib.request.Request(url, headers={"User-Agent": "replicate-local/1.0"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = resp.read()
            ct = resp.headers.get("Content-Type")
        if data is None:
            raise ValueError("Empty response")
        byte_size = len(data)
        ext = _guess_ext(ct, url)
        final_path = local_path + ext

        with open(tmp_path, "wb") as f:
            f.write(data)
        # atomic-ish replace
        try:
            if os.path.exists(final_path):
                os.remove(final_path)
        except Exception:
            pass
        os.replace(tmp_path, final_path)

        entry["local_path"] = final_path
        entry["content_type"] = ct
        entry["byte_size"] = byte_size
        entry["downloaded_at"] = now
        entry["status"] = "cached"
        entry["error_message"] = None
    except Exception as ex:
        # keep any prior cached file if exists; just record error
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception:
            pass
        entry["status"] = "error"
        entry["error_message"] = str(ex)

    entry["last_viewed_at"] = now
    entry["updated_at"] = now
    _save("image_cache_entries.json", entries)

    # open in browser (best-effort)
    opened = False
    if open_in_browser:
        try:
            opened = bool(webbrowser.open(url))
        except Exception:
            opened = False

    if authed_key is not None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    _log("ok", None)
    return {
        "cache_entry": entry,
        "opened_in_browser": opened,
        "prediction_id": prediction_id
    }

def clear_image_cache(mode=None, older_than_days=None, dry_run=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    api_keys = _load("api_keys.json")
    authed_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            authed_key = k
            break

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status, error_code=None):
        entry = {
            "id": "rplog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "clear_image_cache",
            "api_key_id": authed_key.get("id") if isinstance(authed_key, dict) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        request_logs.append(entry)
        _save("request_logs.json", request_logs)

    # Rate limit
    if authed_key is not None:
        rpm = authed_key.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized API key context available for this operation.")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != authed_key.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            _log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    if mode is None:
        mode = "all"
    if mode not in ("all", "evicted", "error"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mode must be one of: all, evicted, error.", field="mode")

    if older_than_days is not None:
        if not isinstance(older_than_days, int) or older_than_days < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "older_than_days must be an integer >= 1.", field="older_than_days")

    if dry_run is None:
        dry_run = False
    if not isinstance(dry_run, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dry_run must be a boolean.", field="dry_run")

    entries = _load("image_cache_entries.json")
    if not isinstance(entries, list):
        entries = []

    cutoff_dt = None
    if older_than_days is not None:
        cutoff_dt = datetime.datetime.utcnow() - datetime.timedelta(days=older_than_days)

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _matches(e):
        if not isinstance(e, dict):
            return False
        st = e.get("status")
        if mode == "evicted" and st != "evicted":
            return False
        if mode == "error" and st != "error":
            return False
        if cutoff_dt is not None:
            # use last_viewed_at if available, else downloaded_at, else created_at
            ref = _dt(e.get("last_viewed_at")) or _dt(e.get("downloaded_at")) or _dt(e.get("created_at"))
            if ref is None:
                return False
            if ref >= cutoff_dt:
                return False
        return True

    matched = [e for e in entries if _matches(e)]
    matched_count = len(matched)

    affected = 0
    bytes_freed = 0

    if not dry_run:
        for e in matched:
            # idempotent eviction: set status and null fields; remove file if exists
            lp = e.get("local_path")
            if e.get("status") == "cached" and isinstance(e.get("byte_size"), int):
                bytes_freed += int(e.get("byte_size") or 0)
            if isinstance(lp, str) and lp:
                try:
                    if os.path.exists(lp):
                        os.remove(lp)
                except Exception:
                    pass
            e["status"] = "evicted"
            e["local_path"] = None
            e["byte_size"] = None
            e["content_type"] = None
            e["error_message"] = None
            e["updated_at"] = now
            affected += 1
        _save("image_cache_entries.json", entries)

        # No success without effect for mutations: if nothing matched, return NOT_FOUND
        if matched_count == 0:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "No cache entries matched the requested clear criteria.")
    else:
        # dry run is read-only; allow zero
        pass

    if authed_key is not None:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    _log("ok", None)
    return {
        "mode": mode,
        "older_than_days": older_than_days,
        "dry_run": dry_run,
        "matched_entries": matched_count,
        "cleared_entries": (0 if dry_run else affected),
        "estimated_bytes_freed": (0 if dry_run else bytes_freed)
    }

def get_image_cache_stats(include_by_status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0268000" if __import__("os").path.isdir("./environment_mix/0268000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")
    authed_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active":
            authed_key = k
            break

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status, error_code=None):
        entry = {
            "id": "rplog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_image_cache_stats",
            "api_key_id": authed_key.get("id") if isinstance(authed_key, dict) else None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        request_logs.append(entry)
        _save("request_logs.json", request_logs)

    # Authorization: not modeled; require at least an active key context
    if authed_key is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to view cache statistics.")

    # Rate limit
    rpm = authed_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to view cache statistics.")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    cnt = 0
    for r in request_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != authed_key.get("id"):
            continue
        ts = r.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        if dt >= cutoff:
            cnt += 1
    if cnt >= rpm:
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if include_by_status is None:
        include_by_status = False
    if not isinstance(include_by_status, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_by_status must be a boolean.", field="include_by_status")

    entries = _load("image_cache_entries.json")
    if not isinstance(entries, list):
        entries = []

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    total_entries = 0
    cached_entries = 0
    evicted_entries = 0
    error_entries = 0
    total_bytes = 0
    oldest = None
    newest = None

    by_status = {"cached": 0, "evicted": 0, "error": 0}

    for e in entries:
        if not isinstance(e, dict):
            continue
        total_entries += 1
        st = e.get("status")
        if st in by_status:
            by_status[st] += 1
        if st == "cached":
            cached_entries += 1
            bs = e.get("byte_size")
            if isinstance(bs, int) and bs >= 0:
                total_bytes += bs
        elif st == "evicted":
            evicted_entries += 1
        elif st == "error":
            error_entries += 1

        dld = _dt(e.get("downloaded_at"))
        if dld is not None:
            if oldest is None or dld < oldest:
                oldest = dld
            if newest is None or dld > newest:
                newest = dld

    # touch api_key
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _log("ok", None)
    resp = {
        "total_entries": total_entries,
        "cached_entries": cached_entries,
        "evicted_entries": evicted_entries,
        "error_entries": error_entries,
        "total_bytes": total_bytes,
        "oldest_downloaded_at": (oldest.isoformat().replace("+00:00", "Z") if oldest is not None else None),
        "newest_downloaded_at": (newest.isoformat().replace("+00:00", "Z") if newest is not None else None),
    }
    if include_by_status:
        resp["by_status"] = by_status
    return resp
